def lora_delta_weight(b_row: list, a_row: list, alpha: float, r: int) -> float:
    """Alpha-scaled LoRA update for one weight entry: (b_row . a_row) * (alpha / r)."""
    dot = sum(b * a for b, a in zip(b_row, a_row))
    return round(dot * (alpha / r), 4)

print(lora_delta_weight([0.2, -0.1, 0.3], [0.4, 0.5, -0.2], 16, 3))

def lora_delta_weight(b_row: list, a_row: list, alpha: float, r: int) -> float:
    dot = sum(b * a for b, a in zip(b_row, a_row))
    return round(dot * (alpha / r), 4)

def lora_merge_weight(w: float, b_row: list, a_row: list, alpha: float, r: int) -> float:
    """Merge a frozen weight with its alpha-scaled LoRA update."""
    delta = lora_delta_weight(b_row, a_row, alpha, r)
    return round(w + delta, 4)

print(lora_merge_weight(0.5, [0.2, -0.1, 0.3], [0.4, 0.5, -0.2], 16, 3))
